// Passenger startup file generated by cloudlinux-selector create from package.json
var NOT_BUILT_PAGE = '<!DOCTYPE html>\n'
    + '<html><head><meta charset="utf-8"><title>The application is not built yet</title></head>\n'
    + '<body><p>cloudlinux-selector: the application is not built yet; run the build and restart</p>'
    + '</body></html>\n';

function notBuiltPage(req, res) {
    res.writeHead(503, { 'Content-Type': 'text/html; charset=utf-8' });
    res.end(NOT_BUILT_PAGE);
}

function serveNotBuilt(missing) {
    console.error('cloudlinux-selector: ' + missing + ' not found, the application is not built yet');
    require('http').createServer(notBuiltPage).listen(process.env.PORT || 3000);
}

// The file require() loads for a request, as `node <file>` resolves it,
// or null when there is none yet.
function resolveOrNull(request) {
    try {
        return require.resolve(request);
    } catch (err) {
        if (err.code !== 'MODULE_NOT_FOUND') {
            throw err;
        }
        return null;
    }
}

var path = require('path');
var NODE_MAJOR = parseInt(process.versions.node.split('.')[0], 10);
var NODE_MINOR = parseInt(process.versions.node.split('.')[1], 10);
// import.meta.main, true only in the module node itself runs as the main
// one (22.18+, 24.2+)
var HAS_IMPORT_META_MAIN = NODE_MAJOR > 24 || (NODE_MAJOR === 24 && NODE_MINOR >= 2)
    || (NODE_MAJOR === 22 && NODE_MINOR >= 18);

// require() refused this very file as an ES module ("Must use import to
// load ES Module: <file>", "require() of ES Module <file> from ...",
// "Requiring <file>" after a top-level await). The same codes for a module
// the file requires come after the file ran, which must not run twice.
function refusedAsModule(err, file) {
    if (err.code !== 'ERR_REQUIRE_ESM' && err.code !== 'ERR_REQUIRE_ASYNC_MODULE') {
        return false;
    }
    var message = String(err.message);
    return ['ES Module ', 'ES Module: ', 'Requiring '].some(function (before) {
        var at = message.indexOf(before + file);
        return at !== -1 && /^(\s|$)/.test(message.slice(at + before.length + file.length));
    });
}

// import(), resolving like an import in the application root (where this
// file is).
function importer() {
    return new Function('specifier', 'return import(specifier)');
}

// A failed start exits with its error, so Passenger reports it at once.
function failed(err) {
    console.error(err);
    process.exit(1);
}

// An ES module, as node's main with asMain: Module.runMain() where node has
// import.meta.main, which is true only there (a failure to load prints the
// error and exits 1, as failed() does); otherwise import() of a file URL,
// so "#", "%" or "?" in a path stay literal.
function importFile(file, asMain) {
    if (asMain && HAS_IMPORT_META_MAIN) {
        require('module').runMain(file);
        return;
    }
    importer()(require('url').pathToFileURL(file).href).catch(failed);
}

// From Node 12 an ES module (.mjs, or declared or guessed by create) is
// imported. Anything else is required, also everything below 12, which
// ignores "type"; from 12 a file require() refuses as an ES module is
// imported instead (the build wrote one where create had nothing to read).
// With asMain it runs as node's main module: process.argv[1] is the file,
// a CommonJS file is require.main (`if (require.main === module) listen()`)
// and an ES module sees import.meta.main where node has it (importFile).
// Without, it is loaded as Passenger loads a startup file, and such guards
// stay false (an app.js that listens outside its guard as well).
function loadFile(file, isModule, asMain) {
    var ext = path.extname(file);
    if (asMain) {
        process.argv[1] = file;
    }
    if (NODE_MAJOR >= 12 && ext !== '.cjs' && (isModule || ext === '.mjs')) {
        importFile(file, asMain);
        return;
    }
    try {
        if (asMain) {
            require('module')._load(file, null, true);
        } else {
            require(file);
        }
    } catch (err) {
        if (NODE_MAJOR < 12 || !refusedAsModule(err, file)) {
            throw err;
        }
        importFile(file, asMain);
    }
}

// Below Node 20.12, which has no --env-file either: KEY=VALUE lines, a
// quoted value unquoted, an unquoted one cut at " #", the later winning.
function parseEnvLines(text) {
    var values = {};
    text.split(/\r?\n/).forEach(function (line) {
        var match = /^\s*(?:export\s+)?([A-Za-z_][A-Za-z0-9_.-]*)\s*=\s*(.*?)\s*$/.exec(line);
        if (match) {
            var quoted = /^(['"`])([\s\S]*?)\1(?:\s+#.*)?$/.exec(match[2]);
            values[match[1]] = quoted ? quoted[2] : match[2].replace(/\s+#.*$/, '');
        }
    });
    return values;
}

// The files of --env-file and --env-file-if-exists as node reads them
// (util.parseEnv, its own parser, from Node 20.12): the later definition
// wins, in a file and across files, and a variable already set (by
// Passenger, from the record) is kept. A missing file is logged and
// skipped: .env is seldom uploaded, the record holds the variables.
function loadEnvFiles(envFiles) {
    var parseEnv = require('util').parseEnv || parseEnvLines;
    var values = {};
    envFiles.forEach(function (envFile) {
        var text;
        try {
            text = require('fs').readFileSync(path.resolve(__dirname, envFile[0]), 'utf8');
        } catch (err) {
            if (err.code !== 'ENOENT') {
                throw err;
            }
            console.error('cloudlinux-selector: ' + envFile[0] + ' not found, continuing without it');
            return;
        }
        var parsed = parseEnv(text);
        Object.keys(parsed).forEach(function (key) {
            values[key] = parsed[key];
        });
    });
    Object.keys(values).forEach(function (key) {
        if (!(key in process.env)) {
            process.env[key] = values[key];
        }
    });
}

// --unhandled-rejections=<mode> as node applies it: strict raises every
// unhandled rejection as an uncaught exception, throw one no other handler
// takes, warn always warns, warn-with-error-code warns and sets the exit
// code when no other handler takes it, none says nothing.
function handleRejections(mode) {
    process.on('unhandledRejection', function (reason) {
        var handled = process.listenerCount('unhandledRejection') > 1;
        if (mode === 'strict' || (mode === 'throw' && !handled)) {
            throw reason;
        }
        if (mode === 'warn' || (mode === 'warn-with-error-code' && !handled)) {
            process.emitWarning('Unhandled promise rejection: ' + (reason && reason.stack || reason),
                'UnhandledPromiseRejectionWarning');
            if (mode === 'warn-with-error-code') {
                process.exitCode = 1;
            }
        }
    });
}

// The node options a running file can still apply.
function applyNodeOptions(options) {
    options.forEach(function (option) {
        var flag = option[0];
        var value = option[1];
        if (flag === '--stack-trace-limit') {
            Error.stackTraceLimit = Number(value);
        } else if (flag === '--unhandled-rejections') {
            handleRejections(value);
        } else if (flag === '--enable-source-maps') {
            if (typeof process.setSourceMapsEnabled === 'function') {
                process.setSourceMapsEnabled(true);
            }
        } else if (flag === '--no-deprecation') {
            process.noDeprecation = true;
        } else if (flag === '--trace-warnings') {
            process.traceProcessWarnings = true;
        }
    });
}

// A -r or --import request that names a file (./, ../, /), which the build
// may write, rather than a package.
function isFile(request) {
    return /^(\.\.?(\/|$)|\/)/.test(request);
}

// What node does before resolving the entry: the start script's
// assignments (NODE_ENV, with nodeEnvWins, over app_mode's, which
// node_wrapper sets, as the command runs in cPanel; NODE_PATH before
// Passenger's, which holds the application's and Passenger's own modules;
// any other for the variables the environment lacks: the record's win, as
// over --env-file), its options, the env files, then the -r modules (hooks
// such as ts-node/register register extensions, so they run before the
// entry is resolved), from the application root as from node's working
// directory. A -r or --import file that is not there yet is "not built
// yet"; a missing package fails the start, as in node. Returns false when
// the page is served.
function prepare(options, nodeEnvWins) {
    options.env.forEach(function (assignment) {
        var name = assignment[0];
        if (name === 'NODE_PATH') {
            var inherited = process.env.NODE_PATH;
            process.env.NODE_PATH = assignment[1] + (inherited ? path.delimiter + inherited : '');
            require('module')._initPaths();
        } else if ((name === 'NODE_ENV' && nodeEnvWins) || !(name in process.env)) {
            process.env[name] = assignment[1];
        }
    });
    applyNodeOptions(options.emulate);
    loadEnvFiles(options.envFiles);
    var missing = options.require.concat(options['import']).filter(function (request) {
        return isFile(request) && !require('fs').existsSync(path.resolve(__dirname, request))
            && (options['import'].indexOf(request) !== -1 || resolveOrNull(path.resolve(__dirname, request)) === null);
    });
    if (missing.length) {
        serveNotBuilt(missing[0]);
        return false;
    }
    options.require.forEach(function (request) {
        require(isFile(request) ? path.resolve(__dirname, request) : request);
    });
    return true;
}

// With --import (node has the option from 18.18 and 20.6; here import()
// from Node 12) the modules are imported first. Then node resolves the main
// the CommonJS way (.js, a directory's main or index.js) and loads it
// through the ES module loader, where the hooks such a module registers
// with module.register() apply: a resolved .js, .cjs or extension-less
// CommonJS file (express-generator's bin/www) runs as require.main here, as
// without --import (import() would not run it as main, and refuses an empty
// extension on 12, 14, 16 and 19), any other file (.ts, ...) is imported;
// when that resolution finds nothing, the path itself is imported, which
// the hooks may resolve (`node --import tsx src/index`, a hook resolving a
// directory). Only the entry itself missing is "not built yet" (see
// entryMissing), not a module the entry imports.
function startWithImports(file, isModule, imports, asMain) {
    if (NODE_MAJOR < 12) {
        throw new Error('--import needs Node.js 12 or later');
    }
    var load = importer();
    imports.reduce(function (done, specifier) {
        return done.then(function () {
            return load(specifier);
        });
    }, Promise.resolve()).then(function () {
        var resolved = resolveOrNull(file);
        var ext = resolved === null ? null : path.extname(resolved);
        if (ext === '' || ext === '.js' || ext === '.cjs' || ext === '.mjs') {
            loadFile(resolved, isModule, asMain);
            return null;
        }
        if (asMain) {
            process.argv[1] = resolved || file;
        }
        return load(require('url').pathToFileURL(resolved || file).href).catch(function (err) {
            if (entryMissing(err, file)) {
                serveNotBuilt(path.relative(__dirname, file) || '.');
                return;
            }
            throw err;
        });
    }).catch(failed);
}

// "Cannot find module '<path>'" or "Directory import '<path>'" naming the
// entry: as given, with an extension a hook tried ('<entry>.ts') or as the
// index a hook resolved a directory to ('<entry>/index.ts'). Any other
// path, also one under the entry's directory, is a module the entry
// imports.
function entryMissing(err, file) {
    if (!err || (err.code !== 'ERR_MODULE_NOT_FOUND' && err.code !== 'ERR_UNSUPPORTED_DIR_IMPORT')) {
        return false;
    }
    var quoted = /'([^']+)'/.exec(String(err.message));
    var named = quoted ? quoted[1] : '';
    if (named.indexOf('file:') === 0) {
        named = require('url').fileURLToPath(named);
    }
    var rest = named.slice(file.length);
    return named.slice(0, file.length) === file && (rest === '' || /^\.[^\/.]+$/.test(rest)
        || /^\/index\.[^\/]+$/.test(rest));
}

function run(file, isModule, options, asMain) {
    if (options['import'].length) {
        startWithImports(file, isModule, options['import'], asMain);
    } else {
        loadFile(file, isModule, asMain);
    }
}

var ENTRY = "dist-server/server.mjs";
var ENTRY_IS_MODULE = true;
var START_OPTIONS = {"env": [["NODE_ENV", "production"]], "require": [], "import": [], "envFiles": [], "emulate": []};
// the start script's NODE_ENV over app_mode's, unless the entry is the
// account's app.js, which keeps app_mode's as before CLOS-7922
var NODE_ENV_WINS = true;
// run as node's main module, unless it is an app.js that listens outside a
// main-module guard as well
var ENTRY_AS_MAIN = true;

if (prepare(START_OPTIONS, NODE_ENV_WINS)) {
    if (START_OPTIONS['import'].length) {
        startWithImports(path.join(__dirname, ENTRY), ENTRY_IS_MODULE, START_OPTIONS['import'], ENTRY_AS_MAIN);
    } else {
        var entry = resolveOrNull(path.join(__dirname, ENTRY));
        if (entry === null) {
            serveNotBuilt(ENTRY);
        } else {
            loadFile(entry, ENTRY_IS_MODULE, ENTRY_AS_MAIN);
        }
    }
}
